use verus::prelude::*;

///////////////////////////////////////////////////////////////////////////////
/// Returns the sign of a 32-bit signed integer:
/// -  1 if x >  0
/// -  0 if x == 0
/// - -1 if x <  0
///////////////////////////////////////////////////////////////////////////////
#[verifier(pure)]
#[requires(true)]
#[ensures(|res: i32| res == if x >  0 {
                               1
                           } else if x < 0 {
                              -1
                           } else {
                              0
                           })]
fn sign_of(x: i32) -> i32 {
    if x > 0 {
        1
    } else if x < 0 {
        -1
    } else {
        0
    }
}

///////////////////////////////////////////////////////////////////////////////
/// Given a vector of 32-bit signed integers, returns a new vector of the same
/// length where each element is replaced by its sign (1, 0, or -1).
///////////////////////////////////////////////////////////////////////////////
#[requires(true)]
#[ensures(|result: Vec<i32>| 
    result.len() == a.len() &&
    (forall |i: usize| i < a.len() ==> result[i] == sign_of(a[i]))
)]
#[decreases(a.len())]
fn sign(a: Vec<i32>) -> Vec<i32> {
    // Preallocate the result to exactly the needed length
    let mut result = Vec::with_capacity(a.len());
    // Map each element through `sign_of` and push into the result
    for &x in &a {
        result.push(sign_of(x));
    }
    result
}

